<script lang="ts">
  import { onMount } from 'svelte'; import { base } from '$app/paths'; import { breachDam, initialEntState, summonEnt, type EntState } from '$lib/ents/dam';
  let state: EntState = initialEntState(); let message = 'The Dam protects this battle.';
  onMount(() => { const p = new URLSearchParams(location.search); if (p.get('summon') === '1') { try { state = summonEnt(state); message = 'An Ent joins the battle.'; } catch { message = 'The Dam protects this battle.'; } } if (p.get('breach') === '1') { state = breachDam({ ...state, protectedBattle: false, summoned: true, draught: 0 }); message = 'The Dam breaks; rewards are doubled.'; } });
</script>
<svelte:head><title>Ents and the Dam — The War for Middle-earth</title></svelte:head>
<main class="ent-shell"><section class="ent-card"><p class="eyebrow">Fangorn · Ent-draught · Dam</p><h1>Wake the Shepherds.</h1><p class="lede">Ents cannot enter a protected battle. Breach the Dam first; the resulting flood doubles its ranked reward.</p><p>Ent-draught: <strong>{state.draught}</strong> · Ent summoned: <strong>{state.summoned ? 'Yes' : 'No'}</strong></p><p>Battle protection: <strong>{state.protectedBattle ? 'Protected' : 'Open'}</strong> · Reward multiplier: <strong>{state.rewardMultiplier}×</strong></p><div class="controls"><a href={`${base}/ents/?summon=1`} data-sveltekit-reload>Summon Ent</a><a class="breach" href={`${base}/ents/?summon=1&breach=1`} data-sveltekit-reload>Breach the Dam</a></div><p role="status" class="message">{message}</p></section></main>
